4. Créer la fenêtre graphique : Utilisez SDL pour créer une fenêtre graphique. Utilisez la fonction SDL_CreateWindow pour créer une fenêtre.

5. Dessinez le fond et le serpent : Utilisez la fonction SDL_RenderCopy pour copier les textures de fond et de serpent sur la fenêtre graphique.

6. Gérer le serpent : Créez une structure pour représenter le serpent, en incluant des informations telles que la position, la taille, et les directions de la tête et de la queue. Utilisez une matrice ou une liste pour stocker les positions des différentes parties du serpent.

7. Gérer le mouvement du serpent : Utilisez la fonction SDL_GetTicks pour obtenir l'heure actuelle en millisecondes, puis utilisez cette valeur pour déterminer la vitesse du serpent. Utilisez les directions de la tête et de la queue pour déterminer la nouvelle position de la tête du serpent, puis vérifiez si la nouvelle position est valide (dans les limites de la fenêtre). Si la nouvelle position est valide, mettez à jour la position de la tête et la taille du serpent.

8. Gérer la collision avec les murs : Vérifiez si la nouvelle position de la tête du serpent est en collision avec les murs de la fenêtre. Si c'est le cas, finissez le jeu.

9. Gérer la collision avec la nourriture : Vérifiez si la nouvelle position de la tête du serpent est en collision avec la nourriture. Si c'est le cas, ajoutez une nouvelle partie au serpent en utilisant la taille actuelle, puis générez une nouvelle position pour la nourriture.

10. Gérer les événements utilisateur : Utilisez SDL pour gérer les événements utilisateur tels que les claviers et la souris. Utilisez les événements pour changer la direction du serpent.

11. Actualiser la fenêtre graphique : Utilisez la fonction SDL_RenderPresent pour actualiser la fenêtre graphique avec les changements effectués dans les étapes précédentes.

12. Lancer un cycle de jeu infini : Utilisez un cycle infini pour continuer à exécuter les étapes 6 à 11 jusqu'à la fin du jeu.

Voici un code de base pour commencer :

```c
#include <SDL2/SDL.h>
#include <stdio.h>

// Constantes pour la taille de la fenêtre
#define WINDOW_WIDTH 640
#define WINDOW_HEIGHT 480

// Constantes pour le serpent
#define SNAKE_SPEED 10 // Millisecondes entre chaque mouvement du serpent

// Constantes pour la nourriture
#define FOOD_SIZE 20

// Structures pour le serpent et la nourriture
typedef struct {
    int x, y;
} SnakePart;

typedef struct {
    int x, y;
} Food;

// Structure pour le serpent entier
typedef struct {
    int snake_length;
    int head_dir_x, head_dir_y;
    int tail_dir_x, tail_dir_y;
    SnakePart parts[100];
} Snake;

// Fonction pour initialiser le serpent
Snake* init_snake() {
    Snake* snake = malloc(sizeof(Snake));
    snake->snake_length = 3;
    snake->head_dir_x = 1;
    snake->head_dir_y = 0;
    snake->tail_dir_x = 0;
    snake->tail_dir_y = 0;
    snake->parts[0].x = WINDOW_WIDTH / 4;
    snake->parts[0].y = WINDOW_HEIGHT / 2;
    snake->parts[1].x = WINDOW_WIDTH / 4 - 20;
    snake->parts[1].y = WINDOW_HEIGHT / 2;
    snake->parts[2].x = WINDOW_WIDTH / 4 - 40;
    snake->parts[2].y = WINDOW_HEIGHT / 2;
    return snake;
}

// Fonction pour initialiser la nourriture
Food* init_food(SDL_Texture* food_texture) {
    Food* food = malloc(sizeof(Food));
    food->x = (rand() % (WINDOW_WIDTH - FOOD_SIZE)) + FOOD_SIZE / 2;
    food->y = (rand() % (WINDOW_HEIGHT - FOOD_SIZE)) + FOOD_SIZE / 2;
    return food;
}

// Fonction pour dessiner le serpent et la nourriture
void draw_snake_and_food(SDL_Renderer* renderer, Snake* snake, Food* food, SDL_Texture* snake_texture, SDL_Texture* food_texture) {
    SDL_Rect snake_rect = { snake->parts[0].x, snake->parts[0].y, 20, 20 };
    SDL_Rect food_rect = { food->x, food->y, FOOD_SIZE, FOOD_SIZE };

    SDL_RenderCopy(renderer, snake_texture, NULL, &snake_rect);
    SDL_RenderCopy(renderer, food_texture, NULL, &food_rect);
}

// Fonction pour gérer le mouvement du serpent
void move_snake(Snake* snake, Food* food) {
    SnakePart* tail = &snake->parts[snake->snake_length - 1];
    SnakePart new_head = {
        .x = snake->parts[0].x + snake->head_dir_x * 20,
        .y = snake->parts[0].y + snake->head_dir_y * 20
    };

    // Mettre à jour la direction de la queue
    tail->x += snake->tail_dir_x * 20;
    tail->y += snake->tail_dir_y * 20;

    // Mettre à jour la tête du serpent
    for (int I = snake->snake_length - 1; I > 0; i--) {
        snake->parts[i] = snake->parts[i - 1];
    }
    snake->parts[0] = new_head;

    // Vérifier si la tête est en collision avec les murs ou la nourriture
    if (new_head.x < 0 || new_head.x >= WINDOW_WIDTH || new_head.y < 0 || new_head.y >= WINDOW_HEIGHT) {
        printf("Game Over!\n");
        exit(0);
    }

    if (new_head.x >= food->x && new_head.x <= food->x + FOOD_SIZE && new_head.y >= food->y && new_head.y <= food->y + FOOD_SIZE) {
        snake->snake_length++;
        food->x = (rand() % (WINDOW_WIDTH - FOOD_SIZE)) + FOOD_SIZE / 2;
        food->y = (rand() % (WINDOW_HEIGHT - FOOD_SIZE)) + FOOD_SIZE / 2;
    }
}

// Fonction principale du jeu
int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_EVERYTHING);

    SDL_Window* window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    SDL_Texture* snake_texture = SDL_LoadBMP("snake.bmp");
    SDL_Texture* food_texture = SDL_LoadBMP("food.bmp");

    Snake* snake = init_snake();
    Food* food = init_food(food_texture);

    Uint32 start_ticks;

    while (1) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_LEFT:
                        if (snake->head_dir_x != 1) {
                            snake->head_dir_x = -1;
                            snake->head_dir_y = 0;
                            snake->tail_dir_x = 0;
                            snake->tail_dir_y = 0;
                        }
                        break;
                    case SDLK_RIGHT:
                        if (snake->head_dir_x != -1) {
                            snake->head_dir_x = 1;
                            snake->head_dir_y = 0;
                            snake->tail_dir_x = 0;
                            snake->tail_dir_y = 0;
                        }
                        break;
                    case SDLK_UP:
                        if (snake->head_dir_y != 1) {
                            snake->head_dir_x = 0;
                            snake->head_dir_y = -1;
                            snake->tail_dir_x = 0;
                            snake->tail_dir_y = 1;
                        }
                        break;
                    case SDLK_DOWN:
                        if (snake->head_dir_y != -1) {
                            snake->head_dir_x = 0;
                            snake->head_dir_y = 1;
                            snake->tail_dir_x = 0;
                            snake->tail_dir_y = -1;
                        }
                        break;
                }
            }
        }

        start_ticks = SDL_GetTicks();

        SDL_RenderClear(renderer);
        draw_snake_and_food(renderer, snake, food, snake_texture, food_texture);
        SDL_RenderPresent(renderer);

        move_snake(snake, food);

        if (SDL_GetTicks() - start_ticks < SNAKE_SPEED) {
            SDL_Delay(SNAKE_SPEED - (SDL_GetTicks() - start_ticks));
        }
    }

    SDL_DestroyTexture(snake_texture);
    SDL_DestroyTexture(food_texture);

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);

    SDL_Quit();

    return 0;
}
```

